-- SPARKLING WINES ALREADY IN THE CATALOG: THEIR SWEETNESS TERM (owner, 2026-10-17; all versions). Run AFTER docs/sparkling_dosage.sql, once,
-- in the Supabase SQL editor (New query, paste all, Run). Safe to run again: every change only touches a wine whose term is still empty.
--
-- Generated from the catalog as read on 2026-10-17 (237 published sparkling wines):
--   1. 217 wines have the term in their name ("Extra Brut Prisme Grand Cru"): the term goes to its own field (basis 'label') and leaves
--      the name ("Prisme Grand Cru"; "Brut" alone leaves an empty name, like a wine known by its producer and place). The old names are kept in
--      wine_name_backup first, so any one can be put back by hand.
--   2. 10 wines with no term in the name: the term was looked up and kept only where a page states it for that wine (basis 'source',
--      with the address). The name stays as it is.
--   3. The others (no term in the name and none found, or sources that disagree) are UNPUBLISHED: set back to "waiting for review", so they leave
--      every deck and show in Editor, Catalog until an editor picks the term in Edit wine info (or "Not on the label") and publishes again.
-- Nothing is deleted.

create table if not exists public.wine_name_backup (
  wine_id  uuid not null,
  name     text,
  reason   text not null,
  saved_at timestamptz not null default now()
);
alter table public.wine_name_backup enable row level security;
drop policy if exists wine_name_backup_read on public.wine_name_backup;
create policy wine_name_backup_read on public.wine_name_backup for select using (has_permission('settings_edit'::text));

-- 1. The term was in the name.
insert into public.wine_name_backup (wine_id, name, reason) select id, name, 'dosage moved out of the name' from public.wines where id = '919527df-277f-5b2b-8cd3-2e19a11f7604' and dosage is null and name = 'Brut Reserva' and not exists (select 1 from public.wine_name_backup b where b.wine_id = '919527df-277f-5b2b-8cd3-2e19a11f7604');
update public.wines set dosage = 'brut', dosage_basis = 'label', name = 'Reserva' where id = '919527df-277f-5b2b-8cd3-2e19a11f7604' and dosage is null and name = 'Brut Reserva';   -- Segura Viudas: Brut Reserva
